// ─── Tagalog Prayer Texts ─────────────────────────────────────────────────────

const kSignOfCrossTl = 'Sa ngalan ng Ama, ng Anak at ng Espiritu Santo. Amen.';

const kApostlesCreedTl =
    '''Sumasampalataya ako sa Diyos Amang makapangyarihan sa lahat, na may gawa ng langit at lupa. Sumasampalataya naman ako kay Hesukristo iisang anak ng Diyos, Panginoon nating lahat. Nagkatawang tao siya lalang ng Espiritu Santo; ipinanganak ni Santang Mariang Birhen. Ipinagpakasakit ni Poncio Pilato; ipinako sa krus, namatay at inilibing. Nanaog sa kinaroroonan ng mga yumao. Nang may ikatlong araw nabuhay na mag-uli. Umakyat sa langit; naluklok sa kanan ng Diyos Amang makapangyarihan sa lahat. Doon magmumula't paririto at huhukom sa nangabubuhay at nangamatay na tao. Sumasampalataya naman ako sa Diyos Espiritu Santo, sa Banal na Simbahang Katolika; sa kasamahan ng mga santo, sa kapatawaran ng mga kasalanan; at sa pagkabuhay na mag-uli ng nangamatay na tao, at sa buhay na walang hanggan. Amen.''';

const kOurFatherTl =
    '''Ama namin sumasalangit ka. Sambahin ang ngalan mo. Mapasaamin ang Kaharian Mo. Sundin ang loob Mo dito sa lupa para nang sa langit. Bigyan Mo kami ngayon ng aming kakanin sa araw araw. At patawarin Mo kami sa aming mga sala, para nang pagpapatawad namin sa nagkakasala sa amin. At huwag mo kaming ipahintulot sa tukso. At iadya mo kami sa lahat ng masama. Amen.''';

const kHailMaryTl =
    '''Aba Ginoong Maria, napupuno ka ng grasya, ang Panginoong Diyos ay sumasaiyo, bukod kang pinagpala sa babaeng lahat at pinagpala naman ang iyong Anak na si Hesus. Santa Maria Ina ng Diyos, ipanalangin mo kaming makasalanan, ngayon at kung kami'm mamamatay. Amen.''';

const kGloryBeTl =
    'Luwalhati sa Ama, sa Anak, sa Espiritu Santo. Kapara noong una, ngayon at magpakailanman at magpasawalang-hanggan. Amen.';

const kFatimaTl =
    'O Hesus ko, patawarin mo kami sa aming mga sala, iligtas mo kami sa apoy ng impiyerno, dalhin Mo ang lahat ng kaluluwa sa langit, lalong-lalo na ang higit na nangangailangan ng iyong awa.';

const kSalveReginaTl =
    '''Aba po Santa Mariang Reyna, Ina ng Awa, Ikaw ang kabuhayan at katamisan; Aba pinananaligan ka naming ikaw nga ang tinatawag namin, pinapanaw na taong anak ni Eva. Ikaw rin ang pinagbubuntuhang hininga namin ng aming pagtangis dini sa lupang bayang kahapis-hapis. Ay aba pintakasi ka namin, ilingon mo sa amin ang mga mata mong maawain, at saka kung matapos yaring pagpanaw sa amin, ipakita mo sa amin ang iyong anak na si Hesus. Santa Maria, Ina ng Diyos, maawain, maalam at matamis na Birhen.\n\nIpanalangin mo kami Reyna ng kasantu-santuhang Rosaryo. Nang kami'y maging dapat makinabang ng mga pangako ni Hesukristo.''';

const kClosingPrayerTl =
    '''O Diyos, na ang kaisa-isa mong Anak, sa pamamagitan ng kanyang buhay, pagkamatay, at pagkabuhay na mag-uli ay ipinagtamo sa amin ang gantimpalang buhay na walang hanggan, ipagkaloob mo, isinasamo namin na sa pagninilay-nilay nitong mga misteryo ng kabanal-banalang Rosaryo ng Pinagpalang Birhen Maria, matularan namin ang kanilang nilalaman, at makamtan namin ang kanilang ipinangangako. Alang-alang kay Kristong aming Panginoon. Amen.''';

